package main

import (
	"context"
	"database/sql"
	"fmt"
)

const schema = `
CREATE TABLE IF NOT EXISTS customers (
	id      TEXT PRIMARY KEY,
	object  TEXT NOT NULL,
	email   TEXT,
	name    TEXT,
	created BIGINT NOT NULL
);
CREATE TABLE IF NOT EXISTS subscriptions (
	id       TEXT PRIMARY KEY,
	object   TEXT NOT NULL,
	customer TEXT,
	status   TEXT,
	created  BIGINT NOT NULL
);`

// tables is the fixed list of mirrored tables, in display order.
var tables = []string{"customers", "subscriptions"}

func CreateTables(ctx context.Context, db *sql.DB) error {
	_, err := db.ExecContext(ctx, schema)
	return err
}

func UpsertCustomers(ctx context.Context, db *sql.DB, cs []Customer) error {
	return inTx(ctx, db, func(tx *sql.Tx) error {
		for _, c := range cs {
			_, err := tx.ExecContext(ctx, `
INSERT INTO customers (id, object, email, name, created) VALUES ($1,$2,$3,$4,$5)
ON CONFLICT (id) DO UPDATE SET object=EXCLUDED.object, email=EXCLUDED.email, name=EXCLUDED.name, created=EXCLUDED.created`,
				c.ID, c.Object, c.Email, c.Name, c.Created)
			if err != nil {
				return fmt.Errorf("upserting customer %s: %w", c.ID, err)
			}
		}
		return nil
	})
}

func UpsertSubscriptions(ctx context.Context, db *sql.DB, ss []Subscription) error {
	return inTx(ctx, db, func(tx *sql.Tx) error {
		for _, s := range ss {
			_, err := tx.ExecContext(ctx, `
INSERT INTO subscriptions (id, object, customer, status, created) VALUES ($1,$2,$3,$4,$5)
ON CONFLICT (id) DO UPDATE SET object=EXCLUDED.object, customer=EXCLUDED.customer, status=EXCLUDED.status, created=EXCLUDED.created`,
				s.ID, s.Object, s.Customer, s.Status, s.Created)
			if err != nil {
				return fmt.Errorf("upserting subscription %s: %w", s.ID, err)
			}
		}
		return nil
	})
}

func inTx(ctx context.Context, db *sql.DB, f func(*sql.Tx) error) error {
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	if err := f(tx); err != nil {
		tx.Rollback()
		return err
	}
	return tx.Commit()
}

func CountRows(ctx context.Context, db *sql.DB, table string) (int64, error) {
	var n int64
	// table always comes from the fixed list above.
	err := db.QueryRowContext(ctx, "SELECT count(*) FROM "+table).Scan(&n)
	return n, err
}
EOF
cat > main.go <<'EOF'
package main

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/lib/pq"
)

const defaultAPIURL = "http://localhost:12111"

const usage = `usage: mirror <command>

commands:
  init     verify the API key, create tables, and import all existing data
  status   print the number of rows in each table

environment:
  MIRROR_DATABASE_URL  Postgres connection string (required)
  MIRROR_API_KEY       API key (required for init)
  MIRROR_API_URL       API base URL (default ` + defaultAPIURL + `)
`

func main() {
	os.Exit(run(context.Background(), os.Args[1:], os.Getenv, os.Stdout, os.Stderr))
}

func run(ctx context.Context, args []string, getenv func(string) string, stdout, stderr io.Writer) int {
	if len(args) != 1 || (args[0] != "init" && args[0] != "status") {
		fmt.Fprint(stderr, usage)
		return 2
	}
	cmd := args[0]

	required := []string{"MIRROR_DATABASE_URL"}
	if cmd == "init" {
		required = append(required, "MIRROR_API_KEY")
	}
	var missing []string
	for _, k := range required {
		if getenv(k) == "" {
			missing = append(missing, k)
		}
	}
	if len(missing) > 0 {
		fmt.Fprintf(stderr, "error: missing required environment variable(s): %s\n", strings.Join(missing, ", "))
		return 1
	}

	db, err := sql.Open("postgres", getenv("MIRROR_DATABASE_URL"))
	if err != nil {
		fmt.Fprintf(stderr, "error: invalid MIRROR_DATABASE_URL: %v\n", err)
		return 1
	}
	defer db.Close()

	switch cmd {
	case "init":
		baseURL := getenv("MIRROR_API_URL")
		if baseURL == "" {
			baseURL = defaultAPIURL
		}
		err = runInit(ctx, db, NewClient(strings.TrimRight(baseURL, "/"), getenv("MIRROR_API_KEY")), stdout)
	case "status":
		err = runStatus(ctx, db, stdout)
	}
	if err != nil {
		fmt.Fprintf(stderr, "error: %v\n", err)
		return 1
	}
	return 0
}

func runInit(ctx context.Context, db *sql.DB, c *Client, out io.Writer) error {
	if err := c.CheckAccount(ctx); err != nil {
		if errors.Is(err, ErrUnauthorized) {
			return fmt.Errorf("MIRROR_API_KEY was rejected by the API: %w", err)
		}
		return fmt.Errorf("checking API key: %w", err)
	}
	if err := CreateTables(ctx, db); err != nil {
		return fmt.Errorf("creating tables: %w", err)
	}
	fmt.Fprintln(out, "API key OK; tables ready")

	var nc, ns int
	if err := c.EachCustomerPage(ctx, func(p []Customer) error {
		nc += len(p)
		return UpsertCustomers(ctx, db, p)
	}); err != nil {
		return fmt.Errorf("importing customers: %w", err)
	}
	fmt.Fprintf(out, "imported %d customers\n", nc)

	if err := c.EachSubscriptionPage(ctx, func(p []Subscription) error {
		ns += len(p)
		return UpsertSubscriptions(ctx, db, p)
	}); err != nil {
		return fmt.Errorf("importing subscriptions: %w", err)
	}
	fmt.Fprintf(out, "imported %d subscriptions\n", ns)
	return nil
}

func runStatus(ctx context.Context, db *sql.DB, out io.Writer) error {
	for _, t := range tables {
		n, err := CountRows(ctx, db, t)
		if err != nil {
			var pe *pq.Error
			if errors.As(err, &pe) && pe.Code == "42P01" {
				return fmt.Errorf("table %q does not exist; run `mirror init` first", t)
			}
			return fmt.Errorf("counting %s: %w", t, err)
		}
		fmt.Fprintf(out, "%s: %d\n", t, n)
	}
	return nil
}
EOF

